def svg(title, content, box='0 0 760 470'):
    prefix = hashlib.sha1(title.encode()).hexdigest()[:8]
    result = f'<svg viewBox="{box}" role="img" aria-label="{html.escape(title)}" xmlns="http://www.w3.org/2000/svg"><title>{html.escape(title)}</title><defs><pattern id="grid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M 32 0 L 0 0 0 32" fill="none" stroke="#d7e2ec" stroke-width=".7"/></pattern><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0 10 5 0 10" fill="#6b8193"/></marker></defs><rect width="100%" height="100%" fill="#f1f5f8"/><rect width="100%" height="100%" fill="url(#grid)"/>{content}</svg>'
    for name in ('grid', 'arrow'):
        result = result.replace(f'id="{name}"', f'id="{prefix}-{name}"').replace(f'url(#{name})', f'url(#{prefix}-{name})')
    return result

